export const CORRECTIONS = {"milk-meat-hygiene--meat-microbiology--เนื้อสัตว์ปนเปื้อนจากไหน-และเชื้อกลุ่มใดสำคัญ":[{"severity":"narrows","lectureSays":"Meat from a healthy animal ควรปราศจาก bacteria หรือสิ่งปนเปื้อนอื่น และการปนเปื้อนเกิดหลักที่ slaughter, storage และ distribution","evidenceSays":"Salmonella อาศัยอยู่ในทางเดินอาหารของโคที่สุขภาพดีได้ตามปกติ แล้วถูกถ่ายทอดมาปนเปื้อนผิว carcass ระหว่าง hide removal และ evisceration ดังนั้นข้อความว่าปราศจากเชื้อจึงจริงเฉพาะกับตัว muscle tissue ไม่ใช่ทั้งตัวสัตว์ งานเดียวกันยังพบ Salmonella เพิ่มขึ้นตามสายการผลิต คือ 18% ใน beef carcass, 39% ใน beef chunk และ 71% ใน ground beef (PMID 26125489, doi 10.1016/j.ijfoodmicro.2015.06.016) ซึ่งสนับสนุนประเด็นของสไลด์เรื่อง distribution และ further processing","examAdvice":"ตอบตามสไลด์ได้ แต่ให้เติมว่ากล้ามเนื้อสัตว์สุขภาพดีปลอดเชื้อ ส่วนลำไส้ไม่ปลอด ซึ่งคือเหตุผลที่ evisceration เป็นจุดวิกฤต","sourceRef":"PMID 26125489"}],"milk-meat-hygiene--meat-molecular--molecular-biology-genomic-techniques-และการปรับปรุงคุณภาพเนื้อ":[{"severity":"narrows","lectureSays":"Genomic techniques คือการรวมกันของ 4 sub-disciplines แต่ในสไลด์ไล่รายชื่อมา 5 ข้อ คือ Genetics, Molecular genetics, Quantitative genetics, Mendelian genetics และ Bioinformatics","evidenceSays":"งาน genomics ในปศุสัตว์เป็นการทำงานร่วมกันของหลายสาขาจริง คือ genome sequencing และ assembly ร่วมกับ bioinformatics การคัดเลือกลักษณะเชิงปริมาณ (quantitative production traits) และการกำจัด deleterious recessive variant ซึ่งเป็นงานฝั่ง Mendelian genetics แต่แหล่งอ้างอิงไม่ได้รับรอง taxonomy ตายตัวว่าต้องเป็น 4 หรือ 5 สาขา (Symposium review: Advances in sequencing technology herald a new frontier in cattle genomics and genome-enabled selection, PMID 32331872, doi 10.3168/jds.2019-17693)","examAdvice":"ถ้าข้อสอบถามจำนวนสาขา ให้ตอบตามสไลด์อาจารย์ และท่องรายชื่อให้ได้ครบทั้ง 5 ข้อที่สไลด์ไล่ไว้","sourceRef":"PMID 32331872"}],"milk-meat-hygiene--meat-quality--เนื้อสดและคุณภาพเนื้อสัตว์":[{"severity":"narrows","lectureSays":"Fresh meat คือเนื้อที่ผ่าน chemical และ physical change หลัง slaughter แต่ผ่าน minimal process เท่านั้น เช่น การตัดแต่งเป็น retail cuts, cubing, grinding, marination และ freezing","evidenceSays":"Codex Code of Hygienic Practice for Meat นิยาม fresh meat แคบกว่านั้น คือเนื้อที่นอกจาก refrigeration แล้วไม่ได้ผ่านการ treat เพื่อการถนอมอาหารด้วยวิธีอื่นนอกจาก protective packaging และยังคง natural characteristics ไว้ การเติม seasoning หรือ additive ทำให้กลายเป็น meat preparation ไม่ใช่ fresh meat ส่วน minced meat และ mechanically separated meat ถูกนิยามแยกไว้ใต้ raw meat","examAdvice":"ถ้าข้อสอบถามตามที่อาจารย์สอน ให้ตอบว่า marination และ grinding ยังนับเป็น fresh meat แต่ถ้าข้อสอบอ้าง Codex ให้ใช้นิยามที่แคบกว่า","sourceRef":"Codex Code of Hygienic Practice for Meat (CXC 58-2005)"}],"milk-meat-hygiene--milk-industry-std--standard-of-milk-collection-center-มาตรฐาน-mcc-ของไทย":[{"severity":"contradicts","lectureSays":"มาตรฐานศูนย์รวบรวมน้ำนมดิบคือ มกษ. 6401(G) – 2560 และเป็นแนวปฏิบัติ (G = guidance) จึงไม่บังคับ","evidenceSays":"ตัวมาตรฐานสินค้าเกษตรเรื่องการปฏิบัติที่ดีสำหรับศูนย์รวบรวมน้ำนมดิบคือ มกษ. 6401-2558 ออกโดยสำนักงานมาตรฐานสินค้าเกษตรและอาหารแห่งชาติ (มกอช./ACFS) ภายใต้ พ.ร.บ. มาตรฐานสินค้าเกษตร พ.ศ. 2551 ตามหน้าศูนย์รวบรวมน้ำนมดิบในระบบสารสนเทศสินค้าเกษตรตามมาตรฐานบังคับของประเทศไทย ส่วนเอกสารเลข มกษ. 6401(G)-2560 ที่พบคือ แนวปฏิบัติในการใช้มาตรฐานสินค้าเกษตร เผยแพร่โดยกรมปศุสัตว์ (certify.dld.go.th) กล่าวคือเป็นคู่มือประกอบการใช้ ไม่ใช่ตัวมาตรฐาน สถานะบังคับหรือไม่บังคับยังตรวจจากตัวบทปฐมภูมิไม่ได้เพราะไฟล์เป็นภาพสแกน","examAdvice":"ถ้าข้อสอบถามเลขมาตรฐาน MCC ให้ตอบ มกษ. 6401(G)-2560 ตามสไลด์อาจารย์ แต่จำไว้ว่าตัวมาตรฐานจริงคือ มกษ. 6401-2558 และควรถามอาจารย์ยืนยันปีก่อนใช้อ้างอิงนอกห้องสอบ","sourceRef":"มกษ. 6401-2558 การปฏิบัติที่ดีสำหรับศูนย์รวบรวมน้ำนมดิบ (มกอช./ACFS) ระบบสารสนเทศสินค้าเกษตรตามมาตรฐานบังคับของประเทศไทย"}],"milk-meat-hygiene--milk-microbiology--microorganisms-in-milk-2-main-groups":[{"severity":"contradicts","lectureSays":"สไลด์จัด Mycobacterium tuberculosis ไว้ในกลุ่ม pathogenic bacteria ที่พบในน้ำนม","evidenceSays":"เชื้อ mycobacterium ที่เป็น milk-borne zoonosis จากโคคือ Mycobacterium bovis ซึ่งเป็นสาเหตุของ bovine tuberculosis ติดต่อสู่คนหลักผ่านการบริโภคน้ำนมที่ไม่ผ่าน pasteurization หรือเนื้อดิบ หรือการสัมผัสใกล้ชิดโคที่ติดเชื้อ โดยคนเป็น incidental host ส่วน M. tuberculosis มีคนเป็น reservoir หลัก (Occupational exposure and challenges in tackling M. bovis at human-animal interface, PMID 33725176, doi 10.1007/s00420-021-01677-z)","examAdvice":"ถ้าข้อสอบให้เลือกเชื้อตามสไลด์ ให้ตอบตามที่อาจารย์สอน แต่ถ้าข้อสอบถามเชื้อ TB ที่ติดจากน้ำนมโคจริง คำตอบคือ M. bovis หรือ M. tuberculosis complex","sourceRef":"PMID 33725176"}],"milk-meat-hygiene--milk-products-storage--dairy-milk-products-definition":[{"severity":"narrows","lectureSays":"Primary sources ของ dairy products คือน้ำนมของ cows (หลัก), goats, sheep, yaks และ camels","evidenceSays":"โคเป็นแหล่งน้ำนมหลักของโลกจริง โดยให้ประมาณ 83% ของน้ำนมและผลิตภัณฑ์นมที่มนุษย์บริโภคทั่วโลก ส่วนที่เหลือมาจาก buffalo, goat, sheep, dromedary camel และ equine species (donkey) ซึ่งสไลด์ไม่ได้ระบุ buffalo และ donkey ไว้เลย ทั้งที่ buffalo เป็นแหล่งน้ำนม non-bovine ที่สำคัญมากในเอเชีย ส่วน yak ที่สไลด์ระบุนั้นงานนี้ไม่ได้ครอบคลุม จึงยืนยันจากแหล่งนี้ไม่ได้ (Composition and aptitude for cheese-making of milk from cows, buffaloes, goats, sheep, dromedary camels, and donkeys, PMID 34955249, doi 10.3168/jds.2021-20961)","examAdvice":"ตอบรายชื่อตามสไลด์ได้ตามปกติ แต่ถ้าข้อสอบเป็นข้อเขียนหรือถามแหล่งน้ำนมในเอเชีย ให้เติมกระบือเข้าไปด้วย","sourceRef":"PMID 34955249"}],"milk-meat-hygiene--milk-raw-storage--milk-collecting-points-จุดรับน้ำนม":[{"severity":"contradicts","lectureSays":"โค 1 ตัวจะรีดน้ำนมได้ไม่เกิน 10 ลิตร/วัน (สไลด์กำกับว่า slide reference number)","evidenceSays":"ไม่พบแหล่งอ้างอิงทางวิชาการที่รองรับเพดาน 10 ลิตร/วัน และตัวเลขนี้ไม่ใช่ค่าทางสรีรวิทยา การศึกษาในโคนม Holstein รายงาน milk yield เฉลี่ย 36 ± 7.8 kg/day (PMID 30879826) ตัวเลขในสไลด์น่าจะเป็นเกณฑ์เชิงปฏิบัติของ milk collecting point ขนาดเล็ก มากกว่าจะเป็นความสามารถในการให้นมของแม่โค","examAdvice":"ถ้าข้อสอบถามเกณฑ์ของจุดรับน้ำนม ให้ตอบ 10 ลิตร/วัน ตามสไลด์อาจารย์ แต่อย่านำตัวเลขนี้ไปตอบเป็นศักยภาพการให้นมของโค","sourceRef":"PMID 30879826"}]};
